SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_skill_page
WHERE status_cd = '00A'
AND page_code = #{dto.pageCode}
AND tenant_id in (#{dto.tenantId}, -1)

  AND page_id != #{dto.pageId}

SELECT page_content
FROM bt_skill_page
WHERE status_cd = '00A'
  AND page_code = #{pageCode}
  AND tenant_id = #{tenantId}

SELECT b.file_id
FROM bt_skill_page a
JOIN bt_file_info b ON a.file_info_id = b.file_info_id AND a.tenant_id = b.tenant_id
WHERE a.status_cd = '00A'
  AND a.page_code = #{pageCode}
  AND a.tenant_id = #{tenantId}
